codeExamples.code:
-- Counterexample: this loses the order relationship.
-- Which order did MUG-BLUE belong to?

create table bad_item_occurrences (
  sku varchar(50),
  quantity integer
);

-- Counterexample: this can collapse separate occurrences of the same SKU.

create table bad_order_lines_by_sku (
  order_id integer not null,
  sku varchar(50) not null,
  quantity integer not null,
  primary key (order_id, sku)
);

CREATE TABLE customers (
  customer_id        bigint PRIMARY KEY,
  customer_email     text NOT NULL,
  loyalty_tier       text NOT NULL
);

CREATE TABLE product_categories (
  product_category_code text PRIMARY KEY,
  product_category_name text NOT NULL,
  category_manager_email text NOT NULL
);

CREATE TABLE products (
  sku                   text PRIMARY KEY,
  product_name          text NOT NULL,
  product_category_code text NOT NULL REFERENCES product_categories(product_category_code)
);

CREATE TABLE orders (
  order_id      bigint PRIMARY KEY,
  order_date    date NOT NULL,
  customer_id   bigint NOT NULL REFERENCES customers(customer_id),
  ship_postcode text NOT NULL
);

CREATE TABLE order_lines (
  order_id             bigint NOT NULL REFERENCES orders(order_id),
  line_no              integer NOT NULL,
  sku                  text NOT NULL REFERENCES products(sku),
  quantity             integer NOT NULL,
  unit_price_at_order  numeric(12, 2) NOT NULL,
  line_discount_amount numeric(12, 2) NOT NULL,
  PRIMARY KEY (order_id, line_no)
);
